package com.smarttask.notification.repository;
import com.smarttask.notification.domain.Notification;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.UUID;
public interface NotificationRepository extends JpaRepository<Notification,UUID>{Page<Notification> findAllByUserIdOrderByCreatedAtDesc(UUID userId,Pageable pageable);long countByUserIdAndReadFalse(UUID userId);long countByReadFalse();long countByCreatedAtGreaterThanEqual(Instant since);java.util.Optional<Notification> findByIdAndUserId(UUID id,UUID userId);@Modifying @Query("update Notification n set n.read=true,n.readAt=:now where n.userId=:userId and n.read=false")int markAllRead(@Param("userId")UUID userId,@Param("now")Instant now);}
